head.b:skin:
/*@STYLE@*/

/* ---------- Blogger の記事本文むけ ---------- */
.entry{margin-bottom:2em}
.entry__title{font-size:clamp(1.4rem,4vw,1.9rem);letter-spacing:.12em;margin-bottom:.8em}
.entry__title a{text-decoration:none}
.entry__body{line-height:2.05}
.entry__body img{border:2px solid var(--frame);box-shadow:4px 4px 0 var(--shadow-color);margin:1.4em 0;max-width:100%;height:auto}
.entry__body h2,.entry__body h3{margin:1.8em 0 .6em}
.entry__body a{color:var(--moss)}
.entry__body blockquote{margin:1.4em 0;padding:.8em 1.2em;border-left:4px solid var(--sage);background:var(--pale)}
.pager{display:flex;gap:.8em;justify-content:center;flex-wrap:wrap;margin-top:2.4em}
.widget-item-control,.quickedit,.post-feeds,.feed-links{display:none}

body.script:
//
(function(){
  var el=document.getElementById('visits');
  if(!el) return;
  var n=1;
  try{
    n=(parseInt(localStorage.getItem('yusurago.visits'),10)||0)+1;
    localStorage.setItem('yusurago.visits',n);
  }catch(e){}
  el.textContent=String(n).padStart(7,'0');
})();
//
